package com.primehr.evidence.domain;import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity@Table(name="evidence_gap")public class EvidenceGap extends RspAuditedEntity{public enum Status{OPEN,RESOLVED,REOPENED}@Column(name="assessment_case_id",nullable=false,length=36)private String assessmentCaseId;@Column(name="requirement_id",nullable=false,length=36)private String requirementId;@Column(name="finding_id",nullable=false,length=36)private String findingId;@Column(nullable=false,length=3000)private String reason;@Column(nullable=false,length=30)private String severity;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="opened_by",nullable=false,length=100)private String openedBy;@Column(name="opened_at",nullable=false)private Instant openedAt;@Column(name="resolved_by",length=100)private String resolvedBy;@Column(name="resolved_at")private Instant resolvedAt;@Column(name="resolution_reason",length=3000)private String resolutionReason;protected EvidenceGap(){}public EvidenceGap(String a,String c,String req,String finding,String reason,String severity,String actor,Instant at){super(a);assessmentCaseId=requiredText(c,"assessmentCaseId");requirementId=requiredText(req,"requirementId");findingId=requiredText(finding,"findingId");this.reason=requiredText(reason,"reason");this.severity=requiredText(severity,"severity").toUpperCase(java.util.Locale.ROOT);status=Status.OPEN;openedBy=requiredText(actor,"actor");openedAt=at;}public void update(String reason,String severity){if(status==Status.RESOLVED)throw new IllegalStateException("Resolved gap cannot be edited");this.reason=requiredText(reason,"reason");this.severity=requiredText(severity,"severity").toUpperCase(java.util.Locale.ROOT);}public void resolve(String actor,String reason,Instant at){if(status==Status.RESOLVED)throw new IllegalStateException("Gap is already resolved");status=Status.RESOLVED;resolvedBy=requiredText(actor,"actor");resolvedAt=at;resolutionReason=requiredText(reason,"reason");}public void reopen(String actor,String reason,Instant at){if(status!=Status.RESOLVED)throw new IllegalStateException("Only a resolved gap may be reopened");status=Status.REOPENED;resolvedBy=null;resolvedAt=null;resolutionReason=requiredText(reason,"reason");openedBy=requiredText(actor,"actor");openedAt=at;}public String getAssessmentCaseId(){return assessmentCaseId;}public String getRequirementId(){return requirementId;}public String getFindingId(){return findingId;}public String getReason(){return reason;}public String getSeverity(){return severity;}public Status getStatus(){return status;}public String getOpenedBy(){return openedBy;}public Instant getOpenedAt(){return openedAt;}public String getResolvedBy(){return resolvedBy;}public Instant getResolvedAt(){return resolvedAt;}public String getResolutionReason(){return resolutionReason;}}
